def main():
    source = BASE.read_bytes().replace(b"\r\n", b"\n")
    digest = hashlib.sha256(source.replace(b"\n", b"\r\n")).hexdigest().upper()
    if digest != BASE_SHA:
        raise SystemExit(f"V90.73 baseline SHA mismatch: {digest}")
    text = source.decode("utf-8")
    for i, (old, new) in enumerate(PATCHES, 1):
        count = text.count(old)
        if count != 1:
            raise SystemExit(f"V90.74 patch {i}: expected 1 match, got {count}")
        text = text.replace(old, new, 1)
    out = text.encode("utf-8")
    (RELEASES / OUT_NAME).write_bytes(out)
    (ROOT / "index.html").write_bytes(out)
    print(f"V90.74 BUILD PASS: {len(PATCHES)} patches, {len(out)} bytes, SHA256 {hashlib.sha256(out).hexdigest().upper()}")

if __name__ == "__main__":
    main()
